package mach.semantic;
import mach.ast.Ast.Span;
import mach.ast.Ast.Type;
import mach.frontend.Diagnostic;
import java.util.*;

/** Backend independent, statically checked signatures of the native core leaves. */
public final class LibraryContracts {
    private LibraryContracts() {}
    private static final Type ANY=new Type("any"),NIL=new Type("nil"),BOOL=new Type("bool"),INT=new Type("int"),STR=new Type("str"),CHAR=new Type("char"),TAG=new Type("tag"),DOUBLE=new Type("double"),FAIL=new Type("fail");
    private static final TypeSystem DEFAULT=new TypeSystem(Map.of(),Map.of());
    private static final ThreadLocal<TypeSystem> CONTEXT=new ThreadLocal<>();
    private static TypeSystem types(){var types=CONTEXT.get();return types==null?DEFAULT:types;}
    private static final Set<String> NUMERIC=Set.of("byte","ubyte","short","ushort","int","uint","long","ulong","float","double","Number","Integer","Signed","Unsigned","Real"),INTEGER=Set.of("byte","ubyte","short","ushort","int","uint","long","ulong","Integer","Signed","Unsigned");
    private static Type vec(Type type){return new Type("vec",List.of(type));}private static Type maybe(Type type){return new Type("maybe",List.of(type));}private static Type attempt(Type type){return new Type("try",List.of(type));}
    private static Type lambda(List<Type> inputs,Type output){var signature=new ArrayList<>(inputs);signature.add(output);return new Type("lambda",List.copyOf(signature));}
    private static Type fail(Span span,String message){throw new Diagnostic("M2201",span,message);}private static void count(List<Type> args,int count,Span span,String selector){if(args.size()!=count)fail(span,selector+" exige "+count+" argumentos");}
    private static void require(Type actual,Type expected,Span span){if(!types().assignable(actual,expected))throw new Diagnostic("M2101",span,"tipo "+actual+" incompatível com "+expected);}
    private static void number(Type actual,Span span){if(!NUMERIC.contains(actual.name()))require(actual,new Type("Number"),span);}private static void integer(Type actual,Span span){if(!INTEGER.contains(actual.name()))fail(span,"argumento deve ser inteiro: "+actual);}
    private static Type function(Type fn,List<Type> inputs,Span span){if(!fn.name().equals("lambda")||fn.args().size()!=inputs.size()+1)return fail(span,"bloco exige "+inputs.size()+" parâmetros");for(int i=0;i<inputs.size();i++)require(inputs.get(i),fn.args().get(i),span);return fn.args().getLast();}
    private static Type callback(List<Type> args,Type block,Span span){if(block!=null)return block;if(args.isEmpty())return fail(span,"mensagem exige bloco");return args.getLast();}
    public static List<Type> expectedBlockInputs(Type receiver,String selector,List<Type> previousArgs){if(receiver==null)return null;if(INTEGER.contains(receiver.name())&&selector.equals("times"))return List.of();if(INTEGER.contains(receiver.name())&&Set.of("upto","downto","step:every").contains(selector))return List.of(receiver);if(receiver.equals(BOOL)&&Set.of("then","otherwise","then:otherwise","and_then","or_else").contains(selector))return List.of();if(Set.of("tap","then_do").contains(selector)&&!receiver.name().equals("lambda"))return List.of(receiver);if(Set.of("map","and_then").contains(selector)&&!Set.of("vec","obj","bool").contains(receiver.name()))return List.of(types().withoutNil(types().successOfTry(receiver)));if(selector.equals("or_else")&&!receiver.equals(BOOL))return List.of(FAIL);return null;}
    public static Type resolve(Type receiver,String selector,List<Type> args,Type block,Span span,TypeSystem types){TypeSystem old=CONTEXT.get();CONTEXT.set(types);try{return resolve(receiver,selector,args,block,span);}finally{if(old==null)CONTEXT.remove();else CONTEXT.set(old);}}
    public static Type resolve(Type receiver,String selector,List<Type> args,Type block,Span span) {
        if(selector.equals("\\\\"))selector="delete";
        Type utility=UtilityContracts.resolve(receiver,selector,args,block,span);if(utility!=null)return utility;
        if(receiver==null){if(Set.of("print","eprint").contains(selector)){count(args,1,span,selector);return NIL;}if(selector.equals("ask")){count(args,1,span,selector);require(args.getFirst(),STR,span);return STR;}if(selector.equals("assert:msg")){count(args,2,span,selector);require(args.getFirst(),BOOL,span);require(args.getLast(),STR,span);return attempt(NIL);}return null;}
        if(receiver.name().equals("type")&&receiver.args().size()==1){Type target=receiver.args().getFirst();if(target.name().equals("Math"))return math(selector,args,span);if(target.name().equals("Fn")){if(selector.equals("identity")){count(args,0,span,selector);return lambda(List.of(ANY),ANY);}if(selector.equals("constant")){count(args,1,span,selector);return lambda(List.of(),args.getFirst());}}if(target.name().equals("Random"))return random(selector,args,span);if(Set.of("max_value","min_value").contains(selector)&&Set.of("byte","ubyte","short","ushort","int","uint","long","ulong","float","double").contains(target.name())){count(args,0,span,selector);return target;}}
        if(receiver.name().equals("Random"))return random(selector,args,span);
        if(NUMERIC.contains(receiver.name())){Type result=numeric(receiver,selector,args,block,span);if(result!=null)return result;}
        if(receiver.equals(STR)){Type result=text(selector,args,span);if(result!=null)return result;}
        if(receiver.equals(CHAR)&&Set.of("code","upcase","downcase","digit?","alpha?","space?","to_str","to_int","succ","pred").contains(selector)){count(args,0,span,selector);return switch(selector){case "code"->INT;case "upcase","downcase"->CHAR;case "succ","pred"->attempt(CHAR);case "to_int"->attempt(INT);case "to_str"->STR;default->BOOL;};}
        if(receiver.name().equals("regex")){if(Set.of("source","flags").contains(selector)){count(args,0,span,selector);return selector.equals("source")?STR:INT;}if(Set.of("match","match?","scan","split","replace:with").contains(selector)){count(args,selector.equals("replace:with")?2:1,span,selector);for(Type arg:args)require(arg,STR,span);return switch(selector){case "match"->maybe(new Type("obj",List.of(maybe(STR))));case "match?"->BOOL;case "scan","split"->vec(STR);default->STR;};}}
        if(receiver.equals(BOOL)){
            if(selector.equals("xor")){count(args,1,span,selector);require(args.getFirst(),BOOL,span);return BOOL;}if(selector.equals("to_int")){count(args,0,span,selector);return INT;}
            if(selector.equals("then:otherwise")){count(args,2,span,selector);Type a=args.getFirst(),b=args.getLast();if(a.name().equals("lambda"))a=function(a,List.of(),span);if(b.name().equals("lambda"))b=function(b,List.of(),span);return types().union(a,b);}
            if(Set.of("then","otherwise").contains(selector)){count(args,block==null?1:0,span,selector);Type fn=callback(args,block,span);return maybe(fn.name().equals("lambda")?function(fn,List.of(),span):fn);}
            if(Set.of("and_then","or_else").contains(selector)){count(args,block==null?1:0,span,selector);require(function(callback(args,block,span),List.of(),span),BOOL,span);return BOOL;}
        }
        if(receiver.name().equals("lambda")){Type result=functional(receiver,selector,args,span);if(result!=null)return result;}
        if(selector.equals("eq")){count(args,1,span,selector);return BOOL;}
        if(selector.equals("unwrap_or")){count(args,1,span,selector);return types().union(types().successOfTry(receiver),args.getFirst());}
        if(selector.equals("unwrap")){count(args,0,span,selector);return types().successOfTry(receiver);}
        if(Set.of("maybe_value","to_maybe").contains(selector)){count(args,0,span,selector);return maybe(types().successOfTry(receiver));}
        if(selector.equals("to_try")){count(args,1,span,selector);return attempt(types().withoutNil(receiver));}
        if(receiver.equals(FAIL)){if(selector.equals("message")){count(args,0,span,selector);return STR;}if(selector.equals("cause")){count(args,0,span,selector);return maybe(FAIL);}if(selector.equals("trace")){count(args,0,span,selector);return vec(STR);}if(selector.equals("wrap")){count(args,1,span,selector);require(args.getFirst(),STR,span);return FAIL;}}
        if(Set.of("or_else","and_then","map").contains(selector)&&!Set.of("vec","obj","lambda").contains(receiver.name())){count(args,block==null?1:0,span,selector);Type input=selector.equals("or_else")?FAIL:types().withoutNil(types().successOfTry(receiver)),output=function(callback(args,block,span),List.of(input),span);if(selector.equals("or_else"))return types().union(types().successOfTry(receiver),output);return types().includesFail(receiver)?attempt(output):types().includesNil(receiver)?maybe(output):output;}
        if(Set.of("copy","inspect","to_str","nil?","present?","frozen?","hash").contains(selector)){count(args,0,span,selector);return switch(selector){case "copy"->receiver;case "inspect","to_str"->STR;case "hash"->new Type("long");default->BOOL;};}
        if(Set.of("tap","then_do").contains(selector)){count(args,block==null?1:0,span,selector);Type output=function(callback(args,block,span),List.of(receiver),span);return selector.equals("tap")?types().includesFail(output)?attempt(receiver):receiver:output;}
        return null;
    }
    private static Type numeric(Type receiver,String selector,List<Type> args,Type block,Span span){
        if(selector.equals("times")&&INTEGER.contains(receiver.name())){count(args,block==null?1:0,span,selector);Type output=function(callback(args,block,span),List.of(),span);return types().includesFail(output)?attempt(NIL):NIL;}
        if(Set.of("upto","downto","step:every").contains(selector)&&INTEGER.contains(receiver.name())){count(args,selector.equals("step:every")?2:1,span,selector);for(Type arg:args)require(arg,receiver,span);Type output=function(callback(List.of(),block,span),List.of(receiver),span);return types().includesFail(output)?attempt(NIL):NIL;}
        if(Set.of("abs","zero?","positive?","negative?","sign","succ","pred","sqrt","cbrt","to_double","to_float","to_int","to_long","to_str","round","floor","ceil","trunc","nan?","infinite?","finite?","even?","odd?","prime?","digits","bit_length","to_char","factorial").contains(selector)&&args.isEmpty()){
            if(Set.of("even?","odd?","prime?","digits","bit_length","to_char","factorial").contains(selector))integer(receiver,span);
            return switch(selector){case "zero?","positive?","negative?","even?","odd?","prime?","nan?","infinite?","finite?"->BOOL;case "sign","to_int","round","floor","ceil","trunc","bit_length"->INT;case "to_long"->new Type("long");case "to_double","cbrt"->DOUBLE;case "to_float"->new Type("float");case "to_str"->STR;case "sqrt"->attempt(DOUBLE);case "digits"->vec(INT);case "to_char"->attempt(CHAR);case "factorial"->attempt(new Type("ulong"));default->receiver;};}
        if(Set.of("min","max","pow","div","mod","rem","divmod","gcd","lcm","round","format","to_str").contains(selector)){count(args,1,span,selector);Type arg=args.getFirst();if(selector.equals("format")){require(arg,STR,span);return attempt(STR);}if(selector.equals("round")){integer(arg,span);return receiver;}if(selector.equals("to_str")){integer(receiver,span);integer(arg,span);return attempt(STR);}if(Set.of("gcd","lcm").contains(selector)){integer(receiver,span);integer(arg,span);return INT;}require(arg,receiver,span);return switch(selector){case "div","mod","rem"->attempt(receiver);case "divmod"->attempt(vec(receiver));default->receiver;};}
        if(Set.of("clamp","between?","pow:mod").contains(selector)){count(args,2,span,selector);for(Type arg:args)require(arg,receiver,span);if(selector.equals("pow:mod")){integer(receiver,span);return attempt(receiver);}return selector.equals("between?")?BOOL:receiver;}
        return null;
    }
    private static Type text(String selector,List<Type> args,Span span){
        if(Set.of("<",">","<=",">=").contains(selector)){count(args,1,span,selector);require(args.getFirst(),STR,span);return BOOL;}
        if(selector.equals("<<")){count(args,1,span,selector);if(!args.getFirst().equals(CHAR))require(args.getFirst(),STR,span);return STR;}
        if(selector.equals("head")){count(args,0,span,selector);return maybe(CHAR);}if(selector.equals("tail")){count(args,0,span,selector);return STR;}
        if(selector.equals("nth")){count(args,1,span,selector);Type key=args.getFirst();if(key.name().equals("vec")){integer(key.args().getFirst(),span);return attempt(STR);}integer(key,span);return attempt(CHAR);}
        if(Set.of("length","size","upcase","downcase","capitalize","swapcase","title_case","trim","trim_left","trim_right","squeeze","reverse","empty?","blank?","digit?","alpha?","alnum?","space?","upper?","lower?","split_lines","lines","words","chars","bytes","to_tag","to_sym","escape","unescape").contains(selector)){count(args,0,span,selector);return switch(selector){case "length","size"->INT;case "empty?","blank?","digit?","alpha?","alnum?","space?","upper?","lower?"->BOOL;case "lines","split_lines","words"->vec(STR);case "chars"->vec(CHAR);case "bytes"->vec(new Type("ubyte"));case "to_tag","to_sym"->TAG;default->STR;};}
        if(Set.of("repeat","center","take","drop").contains(selector)){count(args,1,span,selector);integer(args.getFirst(),span);return selector.equals("repeat")?attempt(STR):STR;}
        if(selector.equals("delete")){if(args.isEmpty())return fail(span,"delete exige valor");for(Type arg:args)if(!arg.equals(CHAR))require(arg,STR,span);return STR;}
        if(Set.of("has?","starts_with?","ends_with?","index_of","last_index_of","count","split","compare","casecmp").contains(selector)){count(args,1,span,selector);if(!args.getFirst().equals(CHAR))require(args.getFirst(),STR,span);return switch(selector){case "has?","starts_with?","ends_with?"->BOOL;case "index_of","last_index_of"->maybe(INT);case "count","compare","casecmp"->INT;case "split"->vec(STR);default->STR;};}
        if(Set.of("match?","match","scan").contains(selector)){count(args,1,span,selector);require(args.getFirst(),new Type("regex"),span);return selector.equals("match?")?BOOL:selector.equals("match")?maybe(new Type("obj",List.of(maybe(STR)))):vec(STR);}
        if(Set.of("replace:with","replace_first:with").contains(selector)){count(args,2,span,selector);for(Type arg:args)if(!arg.equals(CHAR))require(arg,STR,span);return STR;}
        if(selector.equals("slice:to")){count(args,2,span,selector);for(Type arg:args)integer(arg,span);return attempt(STR);}
        if(Set.of("pad_left:with","pad_right:with").contains(selector)){count(args,2,span,selector);integer(args.getFirst(),span);if(!args.getLast().equals(CHAR))require(args.getLast(),STR,span);return attempt(STR);}return null;
    }
    private static Type functional(Type receiver,String selector,List<Type> args,Span span){List<Type> signature=receiver.args();if(signature.isEmpty())return null;int arity=signature.size()-1;if(selector.equals("arity")){count(args,0,span,selector);return INT;}if(selector.equals("memoize")){count(args,0,span,selector);return receiver;}if(selector.equals("flip")){count(args,0,span,selector);if(arity!=2)return fail(span,"flip exige lambda de dois argumentos");return lambda(List.of(signature.get(1),signature.getFirst()),signature.getLast());}if(selector.equals("partial")){if(args.size()>arity)return fail(span,"argumentos demais para partial");for(int i=0;i<args.size();i++)require(args.get(i),signature.get(i),span);return new Type("lambda",signature.subList(args.size(),signature.size()));}if(selector.equals("curry")){count(args,0,span,selector);Type output=signature.getLast();for(int i=arity-1;i>=0;i--)output=lambda(List.of(signature.get(i)),output);return arity==0?receiver:output;}if(Set.of("compose","then_do").contains(selector)){count(args,1,span,selector);Type fn=args.getFirst();if(!fn.name().equals("lambda")||fn.args().isEmpty())return fail(span,"composição exige lambda");Type first=selector.equals("compose")?fn:receiver,second=selector.equals("compose")?receiver:fn;if(second.args().size()!=2)return fail(span,"segunda função deve aceitar um argumento");require(first.args().getLast(),second.args().getFirst(),span);return lambda(first.args().subList(0,first.args().size()-1),second.args().getLast());}return null;}
    private static Type random(String selector,List<Type> args,Span span){if(Set.of("double","bool","uuid").contains(selector)){count(args,0,span,selector);return selector.equals("double")?DOUBLE:selector.equals("bool")?BOOL:STR;}if(selector.equals("seed")){count(args,1,span,selector);integer(args.getFirst(),span);return new Type("Random");}if(selector.equals("bytes")){count(args,1,span,selector);integer(args.getFirst(),span);return attempt(vec(new Type("ubyte")));}if(Set.of("pick","shuffle").contains(selector)){count(args,1,span,selector);Type value=args.getFirst();if(!value.name().equals("vec")||value.args().size()!=1)return fail(span,"coleção deve ser vetor");return selector.equals("pick")?maybe(value.args().getFirst()):value;}if(selector.equals("int")){count(args,2,span,selector);integer(args.getFirst(),span);require(args.getLast(),args.getFirst(),span);return attempt(args.getFirst());}return null;}
    private static Type math(String selector,List<Type> args,Span span){if(Set.of("pi","e","tau","infinity","nan").contains(selector)){count(args,0,span,selector);return DOUBLE;}if(Set.of("sin","cos","tan","asin","acos","atan","sinh","cosh","tanh","exp","ln","log2","log10","sqrt","floor","ceil","round","abs","to_radians","to_degrees").contains(selector)){count(args,1,span,selector);number(args.getFirst(),span);return Set.of("asin","acos","ln","log2","log10","sqrt").contains(selector)?attempt(DOUBLE):DOUBLE;}if(Set.of("atan2:x","hypot:b","log:base","min","max").contains(selector)){count(args,2,span,selector);for(Type arg:args)number(arg,span);return selector.equals("log:base")?attempt(DOUBLE):DOUBLE;}if(Set.of("sum","mean","median","variance","stddev").contains(selector)){count(args,1,span,selector);Type value=args.getFirst();if(!value.name().equals("vec")||value.args().size()!=1)return fail(span,"estatística exige vetor numérico");number(value.args().getFirst(),span);return selector.equals("sum")?DOUBLE:attempt(DOUBLE);}return null;}
}
